"""Reviewed cross-cutting facts for this source tree; not applied to other projects."""
from pathlib import Path
import json
from .render import table,source


def shared(root,d):
    common=root/'output/md/共通';base='input/mcterp/'
    def ref(rel):return source(root,common/'共通仕様.md',base+rel)
    system=['# システム分析 — MCTERP','','## 1. 概要','','入力はERPのWeb画面、モバイル画面、API・業務処理、データアクセス、DB定義、帳票資源から構成される。ソースの業務区分は社員・勤怠・休暇・経費、プロジェクト、SES・請負の見積／受注／発注／請求／入出金、共通マスタ、EUC帳票である。顧客法人名と正式な製品作成者は未確定。個々のコードヘッダの作成者を契約上の作成者とはみなさない。','']
    packages=[]
    for suffix in ['frontend/package.json','mcterp-mobile-app/package.json']:
        p=root/base/suffix
        if p.exists():
            j=json.loads(p.read_text(encoding='utf-8-sig'))
            for k,v in (j.get('dependencies',{})|j.get('devDependencies',{})).items():
                if k in {'vue','vite','typescript','ant-design-vue','vxe-table','pinia','axios'}:packages.append([suffix,k,v])
    system+=[table(['構成ファイル','技術','宣言バージョン'],packages),'', 'バックエンドのWebServiceは.NETのAPIとして配置される。画面がサービス名・処理名を送信し、サーバーが実装を検索して処理する。宣言されている依存先は稼働環境の存在証明ではない。',ref('backend/WebService/WebService.csproj'),'',table(['解析区分','件数'],list(d['stats']['statuses'].items())),f"\n機能区分は{len(d['features'])}、画面・子部品は{len(d['screens'])}ファイル。機能はサービス境界でまとめ、共通ダイアログやモバイルは区別する。",'', '## 2. 読み取り範囲','','コードはコメント・文字列を区別した字句・括弧解析、Vueはタグ階層、DBダンプは長さ付き定義文字列を用いる。コンパイラによる全型解決や実行試験ではない。Excel／マクロ付き帳票はシート構成の確認までとし、マクロ・計算・印字は実行しない。鍵・フォント等は内容を文書へ取り込まない。','', '## 3. 主要な関連原本','',ref('frontend/src/utils/http/common-service.ts'),ref('backend/WebService/Controllers/WebRequestController.cs')]
    spec=['# 共通仕様','','## 1. 対象と共通業務','','業務サービスを横断する要求の受渡し、認証・権限、DB実行、エラー変換、一覧・ファイル出力を整理する。個別業務の入力条件や更新対象は機能仕様を優先する。画面の表示だけを権限チェックの代替にしない。','', '## 2. API要求・応答','','画面はサービス名、処理名、JSON化した業務データを共通APIへ渡す。通常要求とログイン、ファイルアップロード、ダウンロード、プレビューには別の入口がある。要求モデルの共通項目は各クラスの継承関係に従う。固定のリクエストキーと業務項目を混ぜない。',ref('frontend/src/utils/http/common-service.ts'),'', 'サーバー側では認証済みの要求を受け、サービス実装と処理メソッドを検索し、要求モデルを構成する。セッション情報、ログ、権限を処理の前後で扱う。ソース内の個別の例外扱いを全サービスの免除として拡大しない。',ref('backend/WebService/Controllers/WebRequestController.cs'),'', '## 3. トランザクション','','共通クラスのNolockも接続とトランザクション開始を行う。呼出名だけで「取引なし」と説明しない。Transctionは更新時の共通経路、Lockは直列化分離レベルを指定する経路である。開始処理・前処理・業務処理・後処理・確定の順と、捕捉時の取消・エラー変換を区別する。接続開始がtryの外側にある経路について、共通catchで全ての接続障害を捕捉できると断定しない。',ref('backend/BusinessService/CmBusinessService/ErpCommon/Bases/CmServiceBase.cs'),'', '## 4. 一覧・更新・ファイル','','一覧は検索条件、並び順、ページ条件、総件数と明細を分けて受け渡す。DB処理を呼ぶ画面ではSQL定義まで追跡する。更新時点を渡すSetLock等の経路は、取得後に他の更新があった場合の競合を考慮する。一方、DLL内部の比較や実DB制約の有無は原本だけでは確定できない。','', 'ファイルはテンプレート、生成データ、アップロード、保存先、配信応答を区別する。帳票テンプレートのExcelブックを読んだことと、印字が正しいことは別の検証である。サンプルデータやDBダンプのデータ行は仕様例として流用しない。','', '## 5. 共通UIと通知','','部品の入力・表示・操作を区別する。必須条件、読取専用、操作可否、書式、最大長、繰返しはそれぞれ別の属性である。確認ダイアログの了承と保存完了を同一視せず、取消時に維持すべき値と失敗時の状態はイベントごとに確認する。メッセージ定数、直接表示、DB管理の文面は別経路として扱う。','', '## 6. 未確定範囲','','全権限の組合せ、動的EUCデータソース、外部ライブラリの内部、実行環境設定値、ジョブの実スケジュール、物理DBとの差分、未抽出のインライン処理は追加確認が必要。']
    standards=['# 開発規約','','## 1. 観測した構成と推奨の区別','','現行は画面、要求・応答、Service、変換補助、生成DAO、SQL処理、共通部品を分けている。以下の規約案は今後の変更時の確認基準であり、すべて現行で遵守されているという認定ではない。','', '## 2. 例外と状態','','入力不備、権限不足、排他競合、業務上の不成立、通信・DB障害を区別する。処理失敗後に成功通知しない。利用者向け文面と内部ログを分離し、認証情報・接続文字列・個人データをログや仕様例に出さない。画面の確認取消と例外による中断を別状態で定義する。','', '## 3. DB更新','','更新対象の論理データ、物理列、キー、値の由来、順序、取引境界を定義する。共通トランザクションを通ることと、外部ファイル・メール等が巻き戻ることは同一ではない。楽観ロックの要求値とDB制約を確認する。採番の並行実行、重複送信、再試行は試験例を用意する。','', '## 4. 命名・型・形式','','日本語論理名はDBのCOMMENTと画面表示を照合し、異なる意味の列を同名だけで統合しない。型、NULL、空文字、未設定、0、日付と時刻、整数と小数、文字数とバイト数を区別する。APIサービス名・処理名は大文字小文字も含めて受送信側を照合する。','', '## 5. 検証とリリース','','基本経路、条件境界、対象なし、複数一致、取消、権限、並行更新、失敗後状態を検証する。静的解析の件数一致を業務仕様の完全性と置き換えない。仕様の出典と入力版を固定し、修正時は共通仕様・DB定義・影響機能を再生成する。','', '## 6. 解析ツール側の契約','','対象依存の解析・名称・意味付けはsrc-dynamic/mcterpへ置く。他案件にMCTERPの辞書を持ち込まない。安全性チェックを無効化せず、コード由来の文字列をHTMLとして実行されない形で出力する。未対応資料の状態を残し、バイナリ・鍵・フォントを無断で成果物へ複製しない。']
    return {'システム分析.md':'\n'.join(system)+'\n','共通仕様.md':'\n'.join(spec)+'\n','開発規約.md':'\n'.join(standards)+'\n'}
